flowchart LR
subgraph Metadata
A@{
shape: rect
label: |-
  Literal
  label
}
B@{ seed: &shared "Anchored", label: *shared, shape: doc }
C@{
shape: stadium
label: >-
  Folded
  label
}
D@{ shape: rect, label: 0 }
E@{ shape: rect, label: false }
F@{ shape: rect, label: "false" }
G@{ shape: rect, label: true }
H@{ shape: rect, label: null }
I@{ shape: rect, label: "" }
J@{ shape: rect, label: !!str 123 }
K@{ shape: circle, custom: [one, two, 42] }
end
A --> B --> C
Quoted@{ label: '"Hello"', shape: rect, custom: "One \u0022quote\u007d" }
Clipped@{
shape: rect
label: |
  Clipped line
}

flowchart RL
    A@{ shape: manual-file, label: "File Handling"}
    B@{ shape: manual-input, label: "User Input"}
    C@{ shape: docs, label: "Multiple Documents"}
    D@{ shape: procs, label: "Process Automation"}
    E@{ shape: paper-tape, label: "Paper Records"}

flowchart TD
  %% My image with a constrained aspect ratio
  A@{ img: "https://mermaid.js.org/favicon.svg", label: "My example image label", pos: "t", h: 60, constraint: "on" }

flowchart LR
  A e1@==> B
  e1@{ animate: true }

flowchart LR
  A e1@--> B
  e1@{ animation: fast }

flowchart LR
%% this is a comment A -- text --> B{node}
   A -- text --> B -- text2 --> C

flowchart LR
    A e1@==> B
    A e2@--> C
    e1@{ curve: linear }
    e2@{ curve: natural }

